##### BaseExecuteClient

与PaaS 定制应用集成使用，处理业务的具体程序继承 BaseExecuteClient 抽象类，实现 ExecuteAsync 方法

```C#
/// <summary>
/// PaaS端集成切片实现
/// </summary>
public abstract class BaseExecuteClient<T>
{
    /// <summary>
    /// 执行器入口
    /// </summary>
    /// <param name="request"></param>
    /// <returns></returns>
    public abstract Task<NexusLinkResponse<T>> ExecuteAsync(NexusLinkRequest request);
}
```

**执行端应用Startup.cs 集成 app.UseNexusLink()**

```C#
// startup.cs 文件中增加 
public void Configure(IApplicationBuilder app, IWebHostEnvironment env)
{
   base.ConfigureBase(app);
   app.UseSwagger();
   app.UseSwaggerUI(c => c.SwaggerEndpoint("/swagger/v1/swagger.json", "EZR.Arch.CanalConsumer.ApiHost v1"));
   app.UseRouting();
   app.UseEzrMQueue();

   // 集成 EZR.NexusLink组件
   app.UseNexusLink();
   app.UseAuthorization();
}
```

```C#
/// <summary>
/// 
/// </summary>
public static class NexusLinkExtention
{
    /// <summary>
    /// PaaS应用集成切片服务，适配 WebAPI
    /// </summary>
    /// <param name="app"></param>
    public static void UseNexusLink(this IApplicationBuilder app)
    {
        app.Map(new PathString("/NexusLink/Runsync"), application => NexusLinkHandler.RunSync(application));
    }
}
```

**PaaS 端业务接口实现**

```Java
public class SimpleTask : BaseExecuteClient<CrmVipResponseModel>
{
    /// <summary>
    ///日志构造器
    /// </summary>
    private readonly ILog logger = LogManager.GetLogger(nameof(SimpleTask));

    /// <summary>
    /// 
    /// </summary>
    /// <param name="request"></param>
    /// <returns></returns>
    public override Task<NexusLinkResponse<CrmVipResponseModel>> ExecuteAsync(NexusLinkRequest request)
    {
        logger.Info($"SimpleTask.request:{FastJsonSerializer.ToJson(request)}");
        var model = FastJsonSerializer.FromJson<CrmVipRequestModel>(request.Parameter.ToString());

        var crmVipInfo = new CrmVipResponseModel() 
        { 
            Id = model.Id, 
            Name = "CRM测试用户" 
        };

        return Task.FromResult(
            new NexusLinkResponse<CrmVipResponseModel>()
            {
                Data = crmVipInfo,
                Code = 200
            });
    }
}
```

说明： 实现类集成 BaseExecuteClient 抽象类，实现 ExecuteAsync 重载方法。

#### 配置表结构

```Plain Text
CREATE TABLE `ed_base_nexuslink_cfg` (
  `Id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主键自增',
  `BusiCode` varchar(50) DEFAULT NULL COMMENT '业务标识',
  `BrandId` int(11) DEFAULT NULL COMMENT '品牌编号',
  `AppId` varchar(100) DEFAULT NULL COMMENT '定制应用名称',
  `Assembly` varchar(200) DEFAULT NULL COMMENT '程序集地址',
  `HttpMethod` varchar(50) DEFAULT NULL COMMENT '请求方式,Get/Post',
  `ExecuteUrl` varchar(255) NOT NULL COMMENT '执行的UrlPath'
  `Status` int(11) NOT NULL DEFAULT '0' COMMENT '状态(1-启用, 0-禁用)',
  `CreateTime` datetime DEFAULT NULL COMMENT '创建时间',
  `CreateUser` varchar(50) DEFAULT NULL COMMENT '创建人',
  `UpdateTime` datetime DEFAULT NULL COMMENT '修改时间',
  `UpdateUser` varchar(50) DEFAULT NULL COMMENT '修改人',
  PRIMARY KEY (`Id`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COMMENT='EZR.';
```

